Running command: cd /tmp && cat > mkframe.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <blosc2.h>

int main() {
  blosc_init();
  blosc2_cparams cparams = BLOSC2_CPARAMS_DEFAULTS;
  cparams.clevel = 5;
  cparams.compcode = BLOSC_BLOSCLZ;
  cparams.typesize = 4;
  blosc2_storage storage = {.sequential=true, .path=NULL, .cparams=&cparams, .dparams=NULL};
  blosc2_schunk* schunk = blosc2_schunk_new(storage);
  int32_t data[100];
  for (int i=0;i<100;i++) data[i]=i;
  blosc2_schunk_append_buffer(schunk, data, sizeof(data));
  blosc2_schunk_append_buffer(schunk, data, sizeof(data));
  uint8_t* sframe;
  int64_t len = blosc2_schunk_to_sframe(schunk, &sframe);
  printf("frame len %lld\n", (long long)len);
  FILE* f = fopen("/tmp/frame.bin","wb");
  fwrite(sframe, 1, len, f);
  fclose(f);
  blosc2_schunk_free(schunk);
  blosc_destroy();
  return 0;
}
EOF
